#!/usr/bin/env node
/**
 * TRED — le tuteur ne peut plus nier tes documents.
 *
 *     node <chemin>\tred-tuteur-voit.mjs
 *
 * CE QUI S'EST PASSE
 *
 * Le tuteur a repondu "je ne vois aucun fichier des conversations
 * precedentes, chaque nouvelle conversation part de zero" -- alors que neuf
 * documents etaient a l'ecran.
 *
 * Diagnostic, dans l'ordre :
 *   - la base est saine : 9 documents, 88 805 caracteres, tous rattaches.
 *   - la selection de contexte a ete rejouee sur des donnees de cette forme :
 *     elle rend TOUJOURS des documents, jamais une liste vide.
 *   - donc le modele avait bien 9 documents et 24 000 caracteres sous les
 *     yeux, et les a nies quand meme.
 *
 * DEUX DEFAUTS CORRIGES
 *
 *   1. Rien dans le prompt ne disait que ces documents APPARTIENNENT a
 *      l'etudiant et sont conserves d'une conversation a l'autre. Le modele a
 *      raisonne depuis son idee generale ("je n'ai pas de memoire entre
 *      sessions") au lieu des fichiers qu'on lui donnait. Le prompt le dit
 *      maintenant, et INTERDIT explicitement de pretendre ne rien voir.
 *
 *   2. `sources` ne contient que les extraits retenus pour la question --
 *      cinq documents sur neuf, parfois. Le tuteur ne pouvait donc pas savoir
 *      que les quatre autres existaient, et disait "je ne l'ai pas" a propos
 *      d'un fichier visible dans la barre laterale. Il recoit desormais
 *      l'INVENTAIRE COMPLET (titre, type, nombre de pages) en plus des
 *      extraits.
 *
 *      Et la formule change : "dans les passages que j'ai devant moi pour
 *      cette question, ce n'est pas la -- demande-le-moi precisement" au lieu
 *      de "ce document n'existe pas".
 *
 *   3. La branche "aucun document" ne dit plus "tu n'as rien televerse" mais
 *      "rien dans CETTE selection" -- et suggere de changer de semestre ou de
 *      choisir Alle Materialien.
 *
 * Aucune migration. Redeploie et le tuteur change de comportement.
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) { console.error("\n  x  Depot introuvable.\n"); process.exit(1); }

const FILES = {
"packages/web/src/api/agent/index.ts": "",
"packages/web/src/api/index.ts": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}

console.log(`
  Aucune migration. Commit, push, et Railway redeploie.

  Pour verifier : rouvre le chat sur "Alle Materialien" et demande
  "welche Unterlagen hast du von mir?". Il doit citer les neuf titres.
`);
